from taf.hw.mcs.devices.topyoung.topyoung import Topyoung
from taf.hw.mcs.devices.topyoung.command import CommandMCS2338A264B16A1


class TOPYOUNGMCS2338A264B16A1(Topyoung):

    _vendor = "TOPYOUNG"
    _model = "MCS2338A2-64B16-A1"
    _version = None

    _DEFAULT_ROW_PORT_NUMBER = 64
    _DEFAULT_COL_PORT_NUMBER = 16

    def __init__(self, **kwargs):
        super(TOPYOUNGMCS2338A264B16A1, self).__init__(**kwargs)
        self._access_ports = kwargs.get("access_ports", None)

    def connect(self):
        self._connect_socket()
        self._create_command()
        self._get_all_output_channels_access_right()

    def _create_command(self):
        self._command = CommandMCS2338A264B16A1(self._socket_client)

    def disconnect(self):
        self._disconnect_socket()

    def _get_all_output_channels_access_right(self):
        if self._access_ports:
            output_channels = self._access_ports
        else:
            output_channels = range(1, self._column_num + 1)

        for output_channel_id in output_channels:
            self._command.get_output_channel_access_right(output_channel_id)
